script:
(function () {
  'use strict';
  // Credit union auto loan: an editable rate sheet (credit tier x term), membership costs and a budget.
  //   Loan = price - down - trade-in + owed (+ sales tax and fees when financed), >= 0.
  //   APR used = rate-sheet APR - autopay discount (not below 0). A blank cell means "not offered".
  //   Payment M = L x i / (1 - (1 + i)^-n), i = APR / 12 (M = L / n at 0%); interest = M x n - L.
  //   Membership and loan costs = joining fee + yearly dues x loan years (rounded up) + loan fee.
  //   Cost of borrowing = interest + membership and loan costs. The best option is the term with the
  //   lowest cost of borrowing whose payment fits the budget (blank budget = no limit).
  // Verified in Node (scratchpad tests/autogroup/cu.test.js): $25,000 at 6% for 60 months = $483.32/mo,
  //   $3,999.20 interest (closed form); $20,000 at 0% for 48 months = $416.67; the next-tier saving equals
  //   the difference of the two closed-form interest totals; blank cells are skipped; blank, zero and
  //   negative inputs show an error with no NaN or Infinity on the page.
  var TERMS = [36, 48, 60, 72, 84];
  var TIERS = ['760 and above', '720 to 759', '680 to 719', '640 to 679', '600 to 639', 'Below 600'];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  function option(o, apr, months) {
    var rate = Math.max(0, apr - o.autopay);
    var pmt = monthlyPayment(o.loan, rate / 100, months);
    var interest = Math.max(0, pmt * months - o.loan);
    var member = o.join + o.dues * Math.ceil(months / 12) + o.loanFee;
    return { months: months, rate: rate, pmt: pmt, interest: interest, member: member, cost: interest + member };
  }

  function rateText(v) { return String(Number(v.toFixed(3))) + '%'; }

  function clearResults() {
    ['cuBestTerm', 'cuBestPay', 'cuBestInterest', 'cuMember', 'cuLoanOut'].forEach(function (id) { setText(id, '–'); });
    setText('cuVerdictTitle', '–'); setText('cuVerdict', ''); setText('cuNextTier', '');
    el('cuTable').innerHTML = ''; el('cuMatrix').innerHTML = '';
  }

  function addCells(tr, cells) {
    cells.forEach(function (text, c) {
      var td = document.createElement(c === 0 ? 'th' : 'td');
      if (c === 0) td.setAttribute('scope', 'row');
      td.textContent = text;
      tr.appendChild(td);
    });
  }

  function update() {
    var o = {
      price: read('cuPrice'), down: read('cuDown', true), trade: read('cuTrade', true), owed: read('cuOwed', true),
      taxRate: read('cuTaxRate', true), fees: read('cuFees', true), autopay: read('cuAutopay', true),
      join: read('cuJoin', true), dues: read('cuDues', true), loanFee: read('cuLoanFee', true),
      budget: read('cuBudget', true), tier: parseInt(el('cuTier').value, 10),
      finance: el('cuFinanceCosts').checked, tradeCredit: el('cuTradeCredit').checked
    };
    var error = el('cuError'), msg = '';
    if (isNaN(o.price) || o.price <= 0) msg = 'Enter a vehicle price greater than $0.';
    else if ([o.down, o.trade, o.owed, o.taxRate, o.fees, o.autopay, o.join, o.dues, o.loanFee, o.budget].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Amounts and rates cannot be negative.';
    else if (o.taxRate > 20) msg = 'Enter a sales tax rate of 20% or less.';
    else if (o.autopay > 5) msg = 'Enter an autopay discount of 5% or less.';

    var sheet = [];
    for (var t = 0; t < TIERS.length && !msg; t++) {
      sheet.push([]);
      for (var c = 0; c < TERMS.length; c++) {
        var raw = String(el('cuR' + t + '_' + TERMS[c]).value).trim();
        var v = raw === '' ? null : Number(raw);
        if (v !== null && (!isFinite(v) || v < 0 || v > 40)) { msg = 'Rate sheet: enter rates from 0% to 40%, or leave a cell blank if that term is not offered.'; break; }
        sheet[t].push(v);
      }
    }
    if (!msg) {
      var taxable = Math.max(0, o.price - (o.tradeCredit ? o.trade : 0));
      var tax = taxable * o.taxRate / 100;
      o.loan = Math.max(0, o.price - o.down - o.trade + o.owed + (o.finance ? tax + o.fees : 0));
      if (o.loan <= 0.005) msg = 'Your down payment and trade-in cover the full cost, so there is nothing to finance.';
      else if (sheet[o.tier].every(function (v) { return v === null; })) msg = 'The rate sheet has no rates for your credit tier.';
    }
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    setText('cuLoanOut', money.format(o.loan));
    var mine = [];
    TERMS.forEach(function (m, c) { if (sheet[o.tier][c] !== null) mine.push(option(o, sheet[o.tier][c], m)); });
    var fits = mine.filter(function (x) { return o.budget === 0 || x.pmt <= o.budget + 0.005; });
    var byCost = function (a, b) { return a.cost - b.cost || a.months - b.months; };
    var best = fits.slice().sort(byCost)[0];

    var body = el('cuTable');
    body.innerHTML = '';
    mine.forEach(function (x) {
      var tr = document.createElement('tr');
      addCells(tr, [x.months + ' months', rateText(x.rate), money.format(x.pmt), money.format(x.interest), money.format(x.member),
                    money.format(x.cost), x === best ? 'Best fit' : (o.budget === 0 || x.pmt <= o.budget + 0.005 ? 'Fits' : 'Over budget')]);
      body.appendChild(tr);
    });

    if (!best) {
      var lowest = mine.slice().sort(function (a, b) { return a.pmt - b.pmt; })[0];
      ['cuBestTerm', 'cuBestPay', 'cuBestInterest', 'cuMember'].forEach(function (id) { setText(id, '–'); });
      setText('cuVerdictTitle', 'No term fits your budget');
      setText('cuVerdict', 'The lowest payment on the sheet for your tier is ' + money.format(lowest.pmt) + ' over ' + lowest.months +
        ' months. A larger down payment, a cheaper vehicle or a better credit tier would bring it within ' + money.format(o.budget) + '.');
    } else {
      setText('cuBestTerm', best.months + ' months at ' + rateText(best.rate));
      setText('cuBestPay', money.format(best.pmt));
      setText('cuBestInterest', money.format(best.interest));
      setText('cuMember', money.format(best.member));
      var longest = mine[mine.length - 1];
      setText('cuVerdictTitle', 'Cheapest choice for you: ' + best.months + ' months');
      setText('cuVerdict', 'Borrowing costs ' + money.format(best.cost) + ' in interest and fees' +
        (longest !== best ? ', ' + money.format(longest.cost - best.cost) + ' less than stretching to ' + longest.months + ' months.' : '.'));
    }

    // What one tier higher would save on the same term.
    var nextText = '';
    if (best && o.tier > 0) {
      var c2 = TERMS.indexOf(best.months), up = sheet[o.tier - 1][c2];
      if (up !== null) {
        var better = option(o, up, best.months);
        nextText = 'Moving up to the ' + TIERS[o.tier - 1] + ' tier would save ' + money.format(Math.max(0, best.interest - better.interest)) +
          ' in interest on the same ' + best.months + '-month loan.';
      }
    } else if (best) {
      nextText = 'You are already in the top credit tier on this rate sheet.';
    }
    setText('cuNextTier', nextText);

    var mx = el('cuMatrix');
    mx.innerHTML = '';
    TIERS.forEach(function (name, t) {
      var tr = document.createElement('tr');
      var cells = [name + (t === o.tier ? ' (you)' : '')];
      TERMS.forEach(function (m, c) {
        cells.push(sheet[t][c] === null ? 'Not offered' : money0.format(option(o, sheet[t][c], m).pmt) + ' / ' +
          money0.format(option(o, sheet[t][c], m).interest));
      });
      addCells(tr, cells);
      mx.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    ['cuForm', 'cuRates'].forEach(function (id) {
      var form = el(id);
      if (!form) return;
      form.addEventListener('input', update);
      form.addEventListener('change', update);
      form.addEventListener('submit', function (e) { e.preventDefault(); });
    });
    if (el('cuForm')) update();
  });
})();
